from django.conf import settings
from django.db import migrations, models


def legacy_quizzes_to_bank(apps, schema_editor):
    """WAVE 3 PART 3: every quiz made before the upgrade keeps working. Its
    questions are copied into the subject's question bank (MCQ, one answer)
    and the quiz gets one 'chosen questions' section with them, in order.
    The old question rows are left as they were."""
    Quiz = apps.get_model("learning", "Quiz")
    Question = apps.get_model("learning", "Question")
    BankQuestion = apps.get_model("learning", "BankQuestion")
    QuizSection = apps.get_model("learning", "QuizSection")
    for quiz in Quiz.objects.select_related("teaching_assignment").all():
        ids = []
        for q in Question.objects.filter(quiz=quiz).order_by("id"):
            b = BankQuestion.objects.create(
                subject_id=quiz.teaching_assignment.subject_id, kind="mcq", text=q.text,
                options=[q.option1, q.option2, q.option3, q.option4],
                answer=[int(q.correct_answer) - 1], marks=max(1, q.marks or 1),
                difficulty="medium", created_by_id=quiz.created_by_id)
            ids.append(b.id)
        if ids:
            QuizSection.objects.create(quiz=quiz, order=1, title="Questions", pick="fixed", question_ids=ids)

